/*
 * A141574  Sums of pairs of the infinite list generated by the flat list of
 *          the factorizations of all integers.
 * https://oeis.org/A141574
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, less
 * Formula:   a(n) = (2n‑1)-th + (2n)-th element of the flat list of prime
 *            factors of all positive integers (including 1)
 * Range:     u8 n <= 84, u16 n <= 84, u32 n <= 84, u64 n <= 84, u128 n <= 84,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

static seq_t *flat = NULL;          /* the flattened list of factors          */
static size_t flat_len = 0;         /* number of elements currently stored    */
static size_t flat_cap = 0;         /* allocated capacity for flat            */
static uint64_t next_integer = 1;   /* next integer to factorise             */

/* Grow the flat array to hold at least n elements. */
static void ensure_flat_cap(size_t n)
{
    if (n > flat_cap)
    {
        size_t new_cap = flat_cap ? flat_cap * 2 : 16;
        if (n > new_cap)
            new_cap = n;
        seq_t *tmp = (seq_t *)realloc(flat, new_cap * sizeof(seq_t));
        if (!tmp)
            abort();
        flat = tmp;
        flat_cap = new_cap;
    }
}

/* Append the prime factors of x to the flat list. */
static void factor_uint64(uint64_t x)
{
    if (x == 1)
    {
        ensure_flat_cap(flat_len + 1);
        flat[flat_len++] = (seq_t)1;
        return;
    }

    uint64_t m = x;
    for (uint64_t d = 2; d <= m / d; ++d)
    {
        while (m % d == 0)
        {
            ensure_flat_cap(flat_len + 1);
            flat[flat_len++] = (seq_t)d;
            m /= d;
        }
    }
    if (m > 1)
    {
        ensure_flat_cap(flat_len + 1);
        flat[flat_len++] = (seq_t)m;
    }
}

/* Ensure that at least 2*n elements have been generated. */
static void generate_pairs(idx_t n)
{
    idx_t need = n * 2;
    while ((idx_t)flat_len < need)
    {
        factor_uint64(next_integer);
        ++next_integer;
    }
}

/* Required OEIS function. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;                    /* undefined but returned safely     */
    generate_pairs(n);
    idx_t idx = 2 * (n - 1);
    return flat[idx] + flat[idx + 1];
}
